window.H5_POLICY_DATA = [{"name": "澳大利亚", "lat": -25.27, "lng": 133.78, "level": 1, "levelText": "已正式生效", "color": "#0f7a43", "labelDx": 11, "labelDy": 4, "desc": "《网络安全修正案》，主流社交平台需采取合理措施阻止 16 岁以下用户注册或保有账号，违规平台处以高额罚金；即时通讯与教育类平台豁免。"}, {"name": "印度尼西亚", "lat": -2.0, "lng": 118.0, "level": 1, "levelText": "已正式生效", "color": "#0f7a43", "labelDx": 11, "labelDy": 4, "desc": "2025 年第 17 号政府条例（PP Tunas）+ 通信与数字部 2026 年第 9 号部长令，2026-03-28 生效；TikTok、Instagram、X、YouTube、Roblox 等高风险平台禁止 16 岁以下注册，存量未成年账号分阶段关停；教育平台有豁免空间，违规可罚款或暂停服务，覆盖约 7000 万未成年网民。"}, {"name": "法国", "lat": 46.8, "lng": 2.2, "level": 2, "levelText": "法案通过·待落地", "color": "#f5c518", "labelDx": -44, "labelDy": 16, "desc": "议会已通过草案，拟禁止 15 岁以下注册社交媒体账号，目前等待宪法委员会合宪审查，尚未正式落地执行。"}, {"name": "英国", "lat": 54.0, "lng": -2.5, "level": 3, "levelText": "立法提案讨论中", "color": "#ed7d1a", "labelDx": -40, "labelDy": -8, "desc": "Ofcom 监管方案，拟对 16 岁以下青少年关闭算法推荐、夜间推送与陌生人私信功能，目前处于立法提案与公众咨询阶段。"}, {"name": "新西兰", "lat": -41.5, "lng": 173.0, "level": 3, "levelText": "立法提案讨论中", "color": "#ed7d1a", "labelDx": 11, "labelDy": 4, "desc": "立法提案计划禁止 16 岁以下人群使用社交媒体，正在征求公众意见，尚未正式通过。"}, {"name": "丹麦", "lat": 56.2, "lng": 9.5, "level": 3, "levelText": "立法提案讨论中", "color": "#ed7d1a", "labelDx": 11, "labelDy": -8, "desc": "议会公开讨论立法方案，考虑为社交媒体设置 15 岁最低使用年龄，尚未形成正式法案。"}, {"name": "德国", "lat": 51.3, "lng": 10.8, "level": 4, "levelText": "框架性保护法规", "color": "#7dbef0", "labelDx": 11, "labelDy": 14, "desc": "《青少年保护法》要求平台对内容进行年龄分级、提供家长管控工具、屏蔽有害青少年内容；不设置硬性社交媒体注册年龄门槛。"}, {"name": "美国", "lat": 39.5, "lng": -98.0, "level": 4, "levelText": "框架性保护法规", "color": "#7dbef0", "labelDx": 11, "labelDy": 4, "desc": "联邦 COPPA 法案要求收集 13 岁以下儿童信息须获家长同意；佛罗里达、加州等各州单独立法提案，部分州提议 14 / 16 岁门槛，但无全国统一社交媒体年龄禁令。"}, {"name": "欧盟", "lat": 50.1, "lng": 4.5, "level": 4, "levelText": "框架性保护法规", "color": "#7dbef0", "labelDx": -36, "labelDy": 4, "desc": "《数字服务法》（DSA）不设统一注册年龄，但强制青少年账号默认开启安全模式、弱化有害算法推送、加强年龄核验；成员国可在此基础上自行加码管控规则。"}];
